CREATE OR REPLACE PACKAGE bench.b4 AS
  TYPE t_rating IS RECORD (
    user_id NUMBER,
    movie_id NUMBER,
    rating NUMBER,
    ts NUMBER
  );
  FUNCTION passthru(p_rows IN SYS_REFCURSOR) RETURN b4_rating_nt PIPELINED;
