CREATE OR REPLACE PACKAGE BODY bench.b4 AS

  FUNCTION passthru(p_rows IN SYS_REFCURSOR) RETURN b4_rating_nt PIPELINED IS
    TYPE t_rating_buf IS TABLE OF t_rating INDEX BY PLS_INTEGER;
    l_r_buf t_rating_buf;
  BEGIN
    LOOP
      FETCH p_rows BULK COLLECT INTO l_r_buf LIMIT 100;
      EXIT WHEN l_r_buf.COUNT = 0;
      FOR i_r IN 1 .. l_r_buf.COUNT LOOP
        PIPE ROW(b4_rating_obj(l_r_buf(i_r).user_id, l_r_buf(i_r).movie_id, l_r_buf(i_r).rating, l_r_buf(i_r).ts));
      END LOOP;
    END LOOP;
    CLOSE p_rows;
    RETURN;
  END passthru;

  FUNCTION run RETURN NUMBER IS
    l_t0 NUMBER;
    l_t1 NUMBER;
  BEGIN
    l_t0 := dbms_utility.get_time();
    insert into ml_ratings_b4(user_id, movie_id, rating, ts)
        select t.user_id, t.movie_id, t.rating, t.ts
        from table(passthru(cursor(select user_id, movie_id, rating, ts from ml_ratings_src))) t;
    l_t1 := dbms_utility.get_time();
    RETURN ((l_t1 - l_t0) * 10);
  END run;
END b4;
